            across = TcCeil(w, tw);
            down = TcCeil(h, th);
            offsTag = 324;
            noffs = TcField(t, r, 324, CapCount);
            if (TcBad(r) != 0) {
                return TcBad(r);
            }
            if (noffs < 0) {
                offsTag = 273;
                noffs = TcField(t, r, 273, CapCount);
                if (TcBad(r) != 0) {
                    return TcBad(r);
                }
            }
            if (noffs < 0) {
                return TcRet(r, Imgcheck.IcFailed());
            }
            cntsTag = 325;
            ncnts = TcField(t, r, 325, CapCount);
            if (TcBad(r) != 0) {
                return TcBad(r);
            }
            if (ncnts < 0) {
                cntsTag = 279;
                ncnts = TcField(t, r, 279, CapCount);
                if (TcBad(r) != 0) {
                    return TcBad(r);
                }
            }
            if (ncnts < 0) {
                return TcRet(r, Imgcheck.IcFailed());
            }
        } else {
