            if (TcBad(r) != 0) {
                return TcBad(r);
            }
            if ((band <= 0) || (band > h)) {
                band = h;
            }
            cw0 = w;
            across = 1;
            down = TcCeil(h, band);
            offsTag = 273;
            noffs = TcField(t, r, 273, CapCount);
            if (TcBad(r) != 0) {
                return TcBad(r);
            }
            if (noffs < 0) {
                return TcRet(r, Imgcheck.IcFailed());
            }
            cntsTag = 279;
            ncnts = TcField(t, r, 279, CapCount);
            if (TcBad(r) != 0) {
                return TcBad(r);
            }
