        if (planar == 1) {
            planes = spp;
        }
        area = unchecked(unchecked(((long) across) * ((long) down)) * ((long) planes));
        if (((long) noffs) < area) {
            return TcRet(r, Imgcheck.IcFailed());
        }
        need = (int) area;
        if (kind == 6) {
            hs = 2;
            vs = 2;
            c = TcField(t, r, 530, 2);
            if (TcBad(r) != 0) {
                return TcBad(r);
            }
            if (c >= 0) {
                if (c != 2) {
                    return TcRet(r, Imgcheck.IcFailed());
                }
                hs = TcVal(t, r, 0);
                vs = TcVal(t, r, 1);
                if ((hs != 1) && ((hs != 2) && (hs != 4))) {
                    return TcRet(r, Imgcheck.IcFailed());
                }
                if ((vs != 1) && ((vs != 2) && (vs != 4))) {
                    return TcRet(r, Imgcheck.IcFailed());
                }
            }
        }
        if (kind == 3) {
