        offsAt = RArr + cm;
        lensAt = offsAt + need;
        emon.Port.CellsGrow(r, cm + (2 * need), 0);
        if (kind == 3) {
            c = TcField(t, r, 320, 196608);
            i = 0;
            while (i < cm) {
                v = TcVal(t, r, i);
                emon.Port.CellsSet(r, RArr + i, v & 65535);
                i += 1;
            }
        }
        c = TcField(t, r, offsTag, CapCount);
        i = 0;
        while (i < need) {
            v = TcVal(t, r, i);
            emon.Port.CellsSet(r, offsAt + i, v);
            i += 1;
        }
        if (ncnts > 0) {
            c = TcField(t, r, cntsTag, CapCount);
        }
        i = 0;
        while (i < need) {
            off = emon.Port.CellsAt(r, offsAt + i);
            if (i < ncnts) {
                n = TcVal(t, r, i);
            } else {
                if (need != 1) {
                    return TcRet(r, Imgcheck.IcFailed());
                }
                n = 0;
                if ((off >= 0) && (off <= emon.Port.CellsAt(r, RSize))) {
                    n = emon.Port.CellsAt(r, RSize) - off;
                }
            }
            if (TcInb(r, off, n) == 0) {
                return TcRet(r, Imgcheck.IcFailed());
            }
            emon.Port.CellsSet(r, lensAt + i, n);
            i += 1;
        }
        emon.Port.CellsSet(r, RTiled, tiled);
        emon.Port.CellsSet(r, RCw, cw0);
        emon.Port.CellsSet(r, RBand, band);
        emon.Port.CellsSet(r, RAcross, across);
        emon.Port.CellsSet(r, RDown, down);
        emon.Port.CellsSet(r, RHs, hs);
        emon.Port.CellsSet(r, RVs, vs);
        emon.Port.CellsSet(r, RPlanes, planes);
        emon.Port.CellsSet(r, RNchunks, need);
        emon.Port.CellsSet(r, RCmapAt, RArr);
        emon.Port.CellsSet(r, ROffsAt, offsAt);
        emon.Port.CellsSet(r, RLensAt, lensAt);
        return Imgcheck.IcOk();
    }
    internal static int TcRun(byte[] t, int frame, int deep, emon.Port.Cells r) {
        int st = TcHead(t, r);
        if (st != 0) {
            return st;
        }
        int first = emon.Port.CellsAt(r, RFirst);
        if (TcValid(t, r, first) == 0) {
            return TcRet(r, Imgcheck.IcFailed());
        }
        int frames = TcCount(t, r, first);
        int x = first;
        int i = 0;
        emon.Port.CellsSet(r, RFrames, frames);
        if ((frame < 0) || (frame >= frames)) {
            return TcRet(r, Imgcheck.IcFailed());
        }
        while (i < frame) {
            x = TcLink(t, r, x);
            i += 1;
        }
        st = TcIfd(t, r, x);
        if (st != 0) {
            return st;
        }
        return TcFrame(t, r, deep);
    }
    public static int TcCheck(byte[] t, int frame, int deep, emon.Port.Cells r) {
        // See the head of the file. The answer is also in the report's `(tr-status)`.
        emon.Port.CellsDrop(r, 0);
        emon.Port.CellsGrow(r, RArr, 0);
        emon.Port.CellsSet(r, RSize, emon.Port.BlobLen(t));
        emon.Port.CellsSet(r, REo, 1);
        emon.Port.CellsSet(r, ROrient, 1);
        emon.Port.CellsSet(r, RPred, 1);
        emon.Port.CellsSet(r, RHs, 1);
        emon.Port.CellsSet(r, RVs, 1);
        emon.Port.CellsSet(r, RPlanes, 1);
        int st = TcRun(t, frame, deep, r);
        emon.Port.CellsSet(r, RStatus, st);
        emon.Port.CellsSet(r, RLeflag, emon.Port.CellsAt(r, RLe));
        return st;
    }
    public static int TcExif(byte[] b, int @base, int size, emon.Port.Cells r) {
        // The first directory of an EXIF blob b[base, base + size): its orientation 1..8 as (tr-eo) and its horizontal and
        // vertical resolution (tr-ex, tr-ey; dots per inch x 100, 0 unknown). A blob that does not read says (1, 0, 0). `r` may be
        // any `Cells`, new or a report in use; it is grown to the report's registers if shorter and only the EXIF fields move.
        if (emon.Port.CellsLen(r) < RArr) {
            emon.Port.CellsGrow(r, RArr - emon.Port.CellsLen(r), 0);
        }
        emon.Port.CellsSet(r, REo, 1);
        emon.Port.CellsSet(r, REx, 0);
        emon.Port.CellsSet(r, REy, 0);
        emon.Port.CellsSet(r, RErr, 0);
        if ((@base < 0) || ((size < 8) || (size > (emon.Port.BlobLen(b) - @base)))) {
            return 0;
        }
        emon.Port.CellsSet(r, RBase, @base);
        emon.Port.CellsSet(r, RSize, size);
        if (TcHead(b, r) != 0) {
            return 0;
        }
        if (TcIfd(b, r, emon.Port.CellsAt(r, RFirst)) != 0) {
            return 0;
        }
        int o = TcInt(b, r, 274, 1);
        int unit = 2;
        emon.Port.CellsSet(r, RErr, 0);
        if ((o >= 1) && (o <= 8)) {
            emon.Port.CellsSet(r, REo, o);
        }
        unit = TcInt(b, r, 296, 2);
        emon.Port.CellsSet(r, RErr, 0);
        o = TcDpi(b, r, 282, unit);
        emon.Port.CellsSet(r, REx, o);
        o = TcDpi(b, r, 283, unit);
        emon.Port.CellsSet(r, REy, o);
        return 0;
    }
